from pysat.solvers import Glucose3
from itertools import combinations
n=22
edge_to_var={}
var_to_edge={}
v=1
for i in range(n):
    for j in range(i+1,n):
        edge_to_var[(i,j)]=v
        var_to_edge[v]=(i,j)
        v+=1
clauses=[]
# no red K5: in every 5-set, at least one blue edge (var true)
for S in combinations(range(n),5):
    clauses.append([edge_to_var[(i,j)] for i,j in combinations(S,2)])
# no blue K4: in every 4-set, at least one red edge (var false)
for S in combinations(range(n),4):
    clauses.append([-edge_to_var[(i,j)] for i,j in combinations(S,2)])
print('vars',v-1,'clauses',len(clauses))
solver=Glucose3()
for c in clauses: solver.add_clause(c)
print('solving')
sat=solver.solve()
print('sat',sat)
if sat:
    model=set(l for l in solver.get_model() if abs(l)<=v-1)
    arr=[]
    for i in range(n):
        for j in range(i+1,n):
            var=edge_to_var[(i,j)]
            arr.append(1 if var in model else 0)
    print(len(arr))
    print(arr)
    # verify
    red5=0; blue4=0
    for S in combinations(range(n),5):
        if all(arr[edge_to_var[(i,j)]-1]==0 for i,j in combinations(S,2)):
            red5+=1; print('red5',S); break
    for S in combinations(range(n),4):
        if all(arr[edge_to_var[(i,j)]-1]==1 for i,j in combinations(S,2)):
            blue4+=1; print('blue4',S); break
    print('viol',red5,blue4)
